import{_ as t,o as a,c as d,a6 as s}from"./chunks/framework.DIp0zHSV.js";const g=JSON.parse('{"title":"Device Identity Manager","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/subsystems/device-identity.md","filePath":"architecture/subsystems/device-identity.md","lastUpdated":1794274588000}'),o={name:"architecture/subsystems/device-identity.md"};function i(r,e,n,c,l,h){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="device-identity-manager" tabindex="-1">Device Identity Manager <a class="header-anchor" href="#device-identity-manager" aria-label="Permalink to &quot;Device Identity Manager&quot;">​</a></h1><blockquote><p><strong>Subsystem</strong>: <code>window.lcards.core.deviceIdentityManager</code><strong>Class</strong>: <code>DeviceIdentityManager</code> (<code>src/core/services/DeviceIdentityManager.js</code>, extends <code>BaseService</code>)</p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>DeviceIdentityManager</code> gives the current browser profile a <strong>stable, human-labelled identity</strong>. The ID is the key for device-scoped settings in the <a href="./scoped-settings.html"><code>ScopedSettingsService</code></a> waterfall and for <code>target_device_ids</code> / <code>target_device_names</code> targeting of LCARdS actions (checked in <code>IntegrationService._isEventTargetedAtMe()</code>).</p><h3 id="what-makes-a-device" tabindex="-1">What makes a &quot;device&quot;? <a class="header-anchor" href="#what-makes-a-device" aria-label="Permalink to &quot;What makes a &quot;device&quot;?&quot;">​</a></h3><p>A <strong>device</strong> in LCARdS is one browser profile on one machine, not the physical hardware: the ID lives in that profile&#39;s <code>localStorage</code>. Two Chrome profiles on the same laptop are two devices; clearing site data makes a new device. This matches how browser_mod and similar integrations handle device identity.</p><table tabindex="0"><thead><tr><th>Concept</th><th>Implementation</th></tr></thead><tbody><tr><td>Stable ID</td><td>UUID v4 stored in <code>localStorage[&#39;lcards_device_id&#39;]</code></td></tr><tr><td>Display name</td><td>Stored in the backend device record; seeded from the user agent; renamed from the config panel or with <code>?lcards_device=</code></td></tr><tr><td>Backend registration</td><td>Heartbeat (<code>lcards/storage/device/set</code>) once per page load, after the integration probe succeeds</td></tr><tr><td>Name at launch</td><td><code>?lcards_device=&lt;name&gt;</code> URL parameter</td></tr></tbody></table><hr><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> dim</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.lcards.core.deviceIdentityManager;</span></span></code></pre></div><h3 id="properties-getters" tabindex="-1">Properties (getters) <a class="header-anchor" href="#properties-getters" aria-label="Permalink to &quot;Properties (getters)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>dim.deviceId</code></td><td><code>string</code></td><td>Stable UUID; same as <code>getDeviceId()</code></td></tr><tr><td><code>dim.displayName</code></td><td><code>string</code></td><td>Current display name; same as <code>getDisplayName()</code></td></tr><tr><td><code>dim.lastSeen</code></td><td><code>string | null</code></td><td>ISO timestamp of this page&#39;s heartbeat, or <code>null</code> before it ran</td></tr><tr><td><code>dim.userAgent</code></td><td><code>string</code></td><td><code>navigator.userAgent</code></td></tr></tbody></table><h3 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th><th>Description</th></tr></thead><tbody><tr><td><code>getDeviceId()</code></td><td><code>string</code></td><td>The UUID; loads it from <code>localStorage</code>, or creates and stores one, on first call</td></tr><tr><td><code>getDisplayName()</code></td><td><code>string</code></td><td>The display name; the seeded user-agent label when none is set yet</td></tr><tr><td><code>setDisplayName(name)</code></td><td><code>Promise&lt;void&gt;</code></td><td>Set the name locally and write <code>display_name</code> to the backend record (skipped silently when the integration is unavailable)</td></tr><tr><td><code>registerHeartbeat()</code></td><td><code>Promise&lt;void&gt;</code></td><td>Read the stored record, then write <code>display_name</code>, <code>last_seen</code> and <code>user_agent</code>. Runs automatically; you rarely call it</td></tr></tbody></table><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dim.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setDisplayName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Kitchen Tablet&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><hr><h2 id="first-load-behaviour" tabindex="-1">First-Load Behaviour <a class="header-anchor" href="#first-load-behaviour" aria-label="Permalink to &quot;First-Load Behaviour&quot;">​</a></h2><p><code>updateHass()</code> runs <code>_init()</code> once, on the first HASS the core distributes:</p><ol><li><strong>UUID</strong>: <code>_loadOrCreateId()</code> reads <code>localStorage[&#39;lcards_device_id&#39;]</code>, or generates a UUID and stores it. If <code>localStorage</code> throws (some private modes), an ephemeral UUID is used for this page load only.</li><li><strong>URL parameter</strong>: <code>?lcards_device=&lt;name&gt;</code> (trimmed) becomes the display name for this page load and is remembered in memory as <code>_urlName</code>. It is not written to <code>localStorage</code>.</li><li><strong>Seed</strong>: with no name yet, <code>_seedDisplayName()</code> derives one from the user agent.</li><li><strong>Heartbeat</strong>: once <code>integrationService.onReady()</code> resolves, and only if <code>integrationService.available</code>, <code>registerHeartbeat()</code> runs: <ul><li>It reads the backend record (<code>lcards/storage/device/get</code>). A stored <code>display_name</code> replaces the seeded name, <strong>unless</strong> this page load has a <code>?lcards_device=</code> name: the URL name always wins.</li><li>It writes <code>display_name</code>, <code>last_seen</code> (now) and <code>user_agent</code> with <code>lcards/storage/device/set</code> (deep merge, so device-scoped settings in the same record are kept).</li></ul></li></ol><p>Without the integration nothing is written anywhere: the name stays in memory and is seeded again on the next load.</p><h3 id="uuid-generation" tabindex="-1">UUID generation <a class="header-anchor" href="#uuid-generation" aria-label="Permalink to &quot;UUID generation&quot;">​</a></h3><p><code>generateUUID()</code> has three tiers, because <code>crypto.randomUUID()</code> exists only in a secure context (HTTPS or <code>localhost</code>) and many Home Assistant installs are reached over plain HTTP on the LAN:</p><ol><li><code>crypto.randomUUID()</code></li><li><code>crypto.getRandomValues()</code> with the v4 version and variant bits set</li><li><code>Math.random()</code> (logged as a warning; not cryptographically secure)</li></ol><hr><h2 id="naming-with-the-url-parameter" tabindex="-1">Naming with the URL Parameter <a class="header-anchor" href="#naming-with-the-url-parameter" aria-label="Permalink to &quot;Naming with the URL Parameter&quot;">​</a></h2><p>Following the <code>?lcards_log_level=debug</code> convention, a device is named with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-home-assistant/lovelace/?lcards_device=Kitchen+Tablet</span></span></code></pre></div><p>The name reaches the backend in that page load&#39;s heartbeat. On later loads <strong>without</strong> the parameter the stored name is read back, so a single visit is enough. A load <strong>with</strong> the parameter renames the device again, which suits kiosk bookmarks. The name persists only through the backend: without the integration the parameter lasts for that page load.</p><hr><h2 id="auto-seeded-display-names" tabindex="-1">Auto-Seeded Display Names <a class="header-anchor" href="#auto-seeded-display-names" aria-label="Permalink to &quot;Auto-Seeded Display Names&quot;">​</a></h2><p><code>_seedDisplayName()</code> builds <code>&lt;Browser&gt;-&lt;Platform&gt;</code> from <code>navigator.userAgent</code>:</p><table tabindex="0"><thead><tr><th>Check (first match wins)</th><th>Platform</th></tr></thead><tbody><tr><td><code>Android</code></td><td><code>Android</code></td></tr><tr><td><code>iPhone</code>, <code>iPad</code> or <code>iPod</code></td><td><code>iPhone</code></td></tr><tr><td><code>Windows</code></td><td><code>Windows</code></td></tr><tr><td><code>Mac OS X</code></td><td><code>Mac</code></td></tr><tr><td><code>Linux</code></td><td><code>Linux</code></td></tr><tr><td><code>CrOS</code></td><td><code>ChromeOS</code></td></tr><tr><td>none</td><td><code>Unknown</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Check (first match wins)</th><th>Browser</th></tr></thead><tbody><tr><td><code>Edg/</code></td><td><code>Edge</code></td></tr><tr><td><code>OPR/</code></td><td><code>Opera</code></td></tr><tr><td><code>Chrome</code></td><td><code>Chrome</code></td></tr><tr><td><code>Safari</code></td><td><code>Safari</code></td></tr><tr><td><code>Firefox</code></td><td><code>Firefox</code></td></tr><tr><td>none</td><td><code>Browser</code></td></tr></tbody></table><p>Examples: <code>Chrome-Android</code>, <code>Safari-iPhone</code>, <code>Edge-Windows</code>, <code>Firefox-Linux</code>. If reading the user agent throws, the name is <code>Unknown-Device</code>.</p><hr><h2 id="config-panel" tabindex="-1">Config Panel <a class="header-anchor" href="#config-panel" aria-label="Permalink to &quot;Config Panel&quot;">​</a></h2><p>The <strong>Users &amp; Devices</strong> tab (<code>src/panels/components/lcards-users-devices-tab.js</code>):</p><ul><li><strong>Current Session</strong> (every user): this browser&#39;s name, UUID and last-seen time; renaming calls <code>setDisplayName()</code>.</li><li><strong>Users</strong> (admins): users with stored settings; clear a user&#39;s overrides.</li><li><strong>Devices</strong> (admins): every registered device with last-seen time; rename (<code>lcards/storage/devices/set</code>) or delete the whole record (<code>lcards/storage/devices/clear</code>).</li></ul><hr><h2 id="backend-storage" tabindex="-1">Backend Storage <a class="header-anchor" href="#backend-storage" aria-label="Permalink to &quot;Backend Storage&quot;">​</a></h2><p>Device data is the flat key <code>_device_&lt;uuid&gt;</code> in the LCARdS store:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;display_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Kitchen Tablet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;last_seen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:    </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-04-12T09:21:05.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;user_agent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:   </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Mozilla/5.0 (Linux; Android ...)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;owner_user_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;9f1c...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>owner_user_id</code> is set by the backend, never by the browser: it is the user signed in on that browser. The UUID lives only in that browser&#39;s <code>localStorage</code>, so every non-admin <code>lcards/storage/device/set</code> (the heartbeat on each page load, device-scoped settings) makes the caller the owner; an admin&#39;s write claims only a record with no owner, so editing a kiosk&#39;s settings from the config panel leaves the kiosk user the owner. <code>device/get</code> (and <code>storage/get</code> of the <code>_device_*</code> key) is for admins and the current owner; a record with no owner (new, from before owners, or whose owner user was deleted) reads for anyone.</p><p>The kiosk case: an admin sets a tablet up first, so the record is the admin&#39;s; then the kiosk user signs in on it. Their first <code>device/get</code> in <code>registerHeartbeat()</code> is refused (<code>unauthorized</code>), so the heartbeat writes <code>last_seen</code> and <code>user_agent</code> first (which makes them the owner), reads the record again and keeps the stored <code>display_name</code> instead of the seeded one (node test <code>tests/core/device-heartbeat-owner.test.js</code>). Device-scoped settings read before that first heartbeat on such a page load come back empty and fall back to the user and global scopes. An admin can still read and edit the record, and can set the owner with <code>lcards/storage/devices/set</code> (<code>data: { owner_user_id }</code>). Rules: <code>custom_components/lcards/device_access.py</code>.</p><p>Device-scoped settings written with <code>ScopedSettingsService.write(key, value, &#39;device&#39;)</code> are extra keys in the same object. The Python action targeting resolves <code>target_device_names</code> against <code>display_name</code> here (case-insensitive).</p><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./scoped-settings.html">Scoped Settings Service</a></li><li><a href="./integration-service.html">Integration Service</a></li><li><a href="./../../configuration/users-devices.html">Users and devices (user guide)</a></li></ul>`,49)])])}const m=t(o,[["render",i]]);export{g as __pageData,m as default};
